/// 문장 1개 — 러시아어 · 한글 독음 · 뜻 · 주요단어.
class SpoonfedSentence {
  final int no;
  final String ru;
  final String reading;
  final String ko;
  final String? note;
  const SpoonfedSentence(this.no, this.ru, this.reading, this.ko, [this.note]);
}

/// 코스 1개 = 문장 100개 묶음.
