  SpoonfedCourse('sp04', '문장 301~400', 301, 400, [
    SpoonfedSentence(301, 'Я хотел место номер 16.', '야 하쪨 몌스따 노몌르 쉬스나챹찌.', '나는 16번 자리를 원했어.', '야: 나는 · 하쪨: 원했어 · 몌스따: 자리를 · 노몌르: 번호를 · 쉬스나챹찌: 16'),
    SpoonfedSentence(302, 'Сколько времени занимает дорога туда?', '스꼴까 브례미니 자니마엩트 다로가 뚜다?', '거기까지 가는데 얼마나 시간이 걸려?', '스꼴까: 얼마를 · 브례미니: 시간들의 · 자니마엩트: 차지하니 · 다로가: 길이 · 뚜다: 거기까지'),
    SpoonfedSentence(303, 'Я занимаюсь спортом.', '야 자니마유씨 스뽀르땀.', '저는 운동 관련 일을 해요.', '야: 나는 · 자니마유씨: 차지된다(종사한다) · 스뽀르땀: 스포츠로'),
    SpoonfedSentence(304, 'Вы занимаетесь музыкой?', '븨 자니마에찌씨 무지까이?', '당신은 음악 관련 일을 하나요?', '븨: 당신은 · 자니마에찌씨: 차지되나요(종사하나요) · 무지까이: 음악으로'),
