    SpoonfedSentence(496, 'Она обещала прийти сегодня вечером.', '아나 아비샬라 쁘리이찌 씨보드냐 볘체람.', '그녀는 오늘 저녁에 오기로 약속했어.', '아나: 그녀는 · 아비샬라: 약속했다 · 쁘리이찌: 올 것을 · 씨보드냐: 오늘 · 볘체람: 저녁에'),
    SpoonfedSentence(497, 'Она принесёт деньги.', '아나 쁘리니쑡트 졘기.', '그녀가 돈을 가져올 거야.', '아나: 그녀는 · 쁘리니쑡트: 가져올 것이다 · 졘기: 돈을'),
    SpoonfedSentence(498, 'Вы принесли документы?', '븨 쁘리니슬리 다꾸몐띄?', '당신은 서류들을 가져왔나요?', '븨: 당신은 · 쁘리니슬리: 가져왔나요 · 다꾸몐띄: 서류들을'),
    SpoonfedSentence(499, 'Я буду ждать тебя в кинотеатре.', '야 부두 즈닽찌 찌뱌 브 끼나찌아뜨례.', '나는 영화관에서 너를 기다릴게.', '야: 나는 · 부두: ~할 것이다 · 즈닽찌: 기다리는 것을 · 찌뱌: 너를 · 브: ~에서 · 끼나찌아뜨례: 영화관에서'),
    SpoonfedSentence(500, 'Я люблю горы больше, чем море.', '야 류블류 고릐 볼쉐, 쳼 모례.', '저는 바다보다 산이 더 좋아요.', '야: 나는 · 류블류: 좋아한다 · 고릐: 산들을 · 볼쉐: 더 크게(많이) · 쳼: ~보다 · 모례: 바다보다'),
  ]),
  SpoonfedCourse('sp06', '문장 501~600', 501, 600, [
    SpoonfedSentence(501, 'Когда ты вернешь мое кольцо?', '까그다 띄 볘르뇨쉬 마요 깔쪼', '너 언제 내 반지를 돌려줄 거야?', '까그다(언제), 띄(너는), 볘르뇨쉬(돌려줄 거니), 마요(나의), 깔쪼(반지를)'),
    SpoonfedSentence(502, 'Сегодня ночью луна светлая и круглая.', '씨보드냐 노치유 루나 스볘뜰라야 이 끄루글라야', '오늘 밤에는 달이 밝고 둥그네요.', '씨보드냐(오늘), 노치유(밤에는), 루나(달이), 스볘뜰라야(밝다), 이(그리고), 끄루글라야(둥글다)'),
    SpoonfedSentence(503, 'Посмотри на тот свет.', '빠스마뜨리 나 똩트 스볱트', '저 불빛을 봐.', '빠스마뜨리(봐라), 나(~를), 똩트(저), 스볱트(빛을)'),
    SpoonfedSentence(504, 'Та звезда самая красивая.', '따 즈비즈다 싸마야 끄라씨바야', '저 별이 가장 아름다워.', '따(저), 즈비즈다(별이), 싸마야(가장), 끄라씨바야(아름답다)'),
    SpoonfedSentence(505, 'Я надеюсь, что вы выиграете.', '야 나졔유씨, 시으또 븨 븨이그라이쩨', '저는 당신이 이기기를 바랍니다.', '야(저는), 나졔유씨(바랍니다), 시으또(~하기를), 븨(당신이), 븨이그라이쩨(이기기를)'),
    SpoonfedSentence(506, 'Я проиграл.', '야 쁘라이그랄', '나는 졌어.', '야(나는), 쁘라이그랄(졌다)'),
