    SpoonfedSentence(561, 'В августе солнце светлое.', '브 아브구스쪠 쏜쩨 스볘뜰라에', '8월에는 해가 쨍쨍해.', '브(~에), 아브구스쪠(8월에), 쏜쩨(해가), 스볘뜰라에(밝다)'),
    SpoonfedSentence(562, 'Сегодня 21 января.', '씨보드냐 드밭찿찌 뼤르바에 인바랴', '오늘은 1월 21일이야.', '씨보드냐(오늘은), 드밭찿찌(20), 뼤르바에(첫번째다), 인바랴(1월의)'),
    SpoonfedSentence(563, 'Я разговаривал с ним по телефону в сентябре и октябре.', '야 라즈가바리발 스 님 빠 찔리포누 브 씬찌브례 이 악찌브례', '나는 9월과 10월에 그와 전화로 이야기했어.', '야(나는), 라즈가바리발(이야기했다), 스(~와), 님(그의), 빠(~를 통해), 찔리포누(전화를), 브(~에), 씬찌브례(9월에), 이(그리고), 악찌브례(10월에)'),
    SpoonfedSentence(564, 'Здесь нельзя громко разговаривать.', '즈졔씨 닐쟈 그롬까 라즈가바리밭찌', '여기서는 시끄럽게 이야기하면 안돼요.', '즈졔씨(여기에서는), 닐쟈(~하면 안된다), 그롬까(큰소리로), 라즈가바리밭찌(이야기하는 것을)'),
    SpoonfedSentence(565, 'Мы надеемся, что война закончится быстро.', '믜 나졔임쌰, 시으또 바이나 자꼰칱짜 븨스뜨라', '우리는 전쟁이 빨리 끝나기를 바랍니다.', '믜(우리는), 나졔임쌰(희망한다), 시으또(~하기를), 바이나(전쟁이), 자꼰칱짜(끝나기를), 븨스뜨라(빠르게)'),
    SpoonfedSentence(566, 'Многие люди погибли именно в этой войне.', '므노기에 류지 빠기블리 이몐나 브 에따이 바이녜', '바로 이 전쟁에서 많은 사람들이 죽었어.', '므노기에(많은), 류지(사람들이), 빠기블리(죽었다), 이몐나(바로), 브(~에서), 에따이(이), 바이녜(전쟁에서)'),
    SpoonfedSentence(567, 'Я надеюсь, ты найдешь свой кошелек.', '야 나졔유씨, 띄 나이죠쉬 스보이 까쉴룤크', '너의 지갑을 찾길 바래.', '야(나는), 나졔유씨(희망한다), 띄(너가), 나이죠쉬(찾기를), 스보이(자신의), 까쉴룤크(지갑을)'),
    SpoonfedSentence(568, 'Где ты нашел эти брюки?', '그졔 띄 나숄 에찌 브류끼', '너는 어디에서 그 바지를 찾았니?', '그졔(어디에서), 띄(너는), 나숄(찾았니), 에찌(이), 브류끼(바지를)'),
    SpoonfedSentence(569, 'Мой стол исчез.', '모이 스똘 이쉬에스', '나의 책상이 사라졌어.', '모이(나의), 스똘(책상은), 이쉬에스(사라졌다)'),
    SpoonfedSentence(570, 'Кошка моего друга вдруг исчезла.', '꼬시으까 마이보 드루가 브드뤀크 이쉬에즐라', '제 친구의 고양이는 갑자기 없어졌어요.', '꼬시으까(고양이는), 마이보(나의), 드루가(친구의), 브드뤀크(갑자기), 이쉬에즐라(사라졌다)'),
    SpoonfedSentence(571, 'Когда ты выбросил ту книгу?', '까그다 띄 브로씰 뚜 끄니구', '너는 언제 그 책을 버렸니?', '까그다(언제), 띄(너는), 브로씰(버렸니), 뚜(그), 끄니구(책을)'),
    SpoonfedSentence(572, 'Я бросил монету в реку.', '야 브로씰 마녜뚜 브 례꾸', '나는 강에 동전을 던졌어.', '야(나는), 브로씰(던졌다), 마녜뚜(동전을), 브(~에), 례꾸(강으로)'),
    SpoonfedSentence(573, 'Там есть красивая река.', '땀 예스찌 끄라씨바야 리까', '그곳에는 아름다운 강이 있어요.', '땀(거기에는), 예스찌(있다), 끄라씨바야(아름다운), 리까(강이)'),
    SpoonfedSentence(574, 'Это дерево очень классное.', '에따 졔례바 오친 끌라스나에', '이 나무는 정말 멋지구나.', '에따(이), 졔례바(나무는), 오친(매우), 끌라스나에(멋지다)'),
    SpoonfedSentence(575, 'В деревне спокойно и красиво.', '브 졔례브녜 스빠꼬이나 이 끄라씨바', '시골은 평온하고 아름다워요.', '브(~에서는), 졔례브녜(시골에서는), 스빠꼬이나(평온하다), 이(그리고), 끄라씨바(아름답다)'),
    SpoonfedSentence(576, 'Твоя одежда тонкая.', '뜨바야 아졔즈다 똔까야', '너의 옷은 얇아.', '뜨바야(너의), 아졔즈다(옷은), 똔까야(얇다)'),
    SpoonfedSentence(577, 'Эти перчатки дорогие, но теплые.', '에찌 뼤르챠뜨끼 다라기에, 노 쬬쁠릐에', '이 장갑은 비싸지만 따뜻해.', '에찌(이), 뼤르챠뜨끼(장갑은), 다라기에(비싸다), 노(하지만), 쬬쁠릐에(따뜻하다)'),
    SpoonfedSentence(578, 'У меня нет теплой одежды.', '우 미냐 녵트 쬬쁠라이 아졔즈듸', '나는 따뜻한 옷이 없어.', '우(~에게는), 미냐(나의), 녵트(없다), 쬬쁠라이(따뜻한), 아졔즈듸(옷의)'),
    SpoonfedSentence(579, 'Сегодня нам надо тепло одеваться.', '씨보드냐 남 나다 찌쁠로 아지밭짜', '오늘 우리는 따뜻하게 옷을 입어야 해.', '씨보드냐(오늘), 남(우리에게는), 나다(~해야한다), 찌쁠로(따뜻하게), 아지밭짜(옷을 입는 것을)'),
    SpoonfedSentence(580, 'Это мясо очень толстое.', '에따 먀싸 오친 똘스따에', '이 고기는 굉장히 두껍네요.', '에따(이), 먀싸(고기는), 오친(매우), 똘스따에(두껍다)'),
    SpoonfedSentence(581, 'Нельзя трогать незнакомого человека.', '닐쟈 뜨로같찌 니즈나꼬마바 칠라볘까', '모르는 사람을 만지면 안돼요.', '닐쟈(~하면 안된다), 뜨로같찌(만지는 것을), 니즈나꼬마바(모르는), 칠라볘까(사람을)'),
    SpoonfedSentence(582, 'Не трогайте мое тело.', '니 뜨로가이쪠 마요 쪨라', '저의 몸을 만지지 마세요.', '니(~아니다), 뜨로가이쪠(만지세요), 마요(나의), 쪨라(몸을)'),
    SpoonfedSentence(583, 'У тебя действительно большое тело.', '우 찌뱌 지이스뜨비찔나 발쇼에 쪨라', '너는 몸이 정말 크구나.', '우(~에게는), 찌뱌(너의), 지이스뜨비찔나(정말로), 발쇼에(큰), 쪨라(몸이)'),
    SpoonfedSentence(584, 'Откройте рот.', '앝끄로이쪠 롵트', '입을 벌리세요.', '앝끄로이쪠(여세요), 롵트(입을)'),
    SpoonfedSentence(585, 'У него немного большой рот и нос.', '우 니보 니므노가 발쇼이 롵트 이 노쓰', '그는 입과 코가 조금 커.', '우(~에게는), 니보(그의), 니므노가(조금), 발쇼이(큰), 롵트(입이), 이(그리고), 노쓰(코가)'),
    SpoonfedSentence(586, 'У меня идет кровь из носа.', '우 미냐 이죹트 끄로프 이즈 노싸', '코에서 피가 나요.', '우(~에게는), 미냐(나의), 이죹트(간다), 끄로프(피가), 이즈(~로부터), 노싸(코의)'),
    SpoonfedSentence(587, 'Пол в комнате грязный.', '뽈 브 꼼나쪠 그랴즈늬이', '방의 바닥이 더러워요.', '뽈(바닥은), 브(~에), 꼼나쪠(방에), 그랴즈늬이(더럽다)'),
    SpoonfedSentence(588, 'Принесите, пожалуйста, чистое полотенце.', '쁘리니씨쪠, 빠좌을스따, 치스따에 빨라쪤쩨', '깨끗한 수건을 가져다 주세요.', '쁘리니씨쪠(가져다 주세요), 빠좌을스따(제발), 치스따에(깨끗한), 빨라쪤쩨(수건을)'),
    SpoonfedSentence(589, 'Мне не очень нравятся лестницы.', '므녜 니 오친 느라뱥짜 례스뜨니쯰', '나는 계단을 별로 좋아하지 않아.', '므녜(나에게는), 니(~아니다), 오친(매우), 느라뱥짜(마음에 든다), 례스뜨니쯰(계단들이)'),
    SpoonfedSentence(590, 'Лифт лучше чем лестницы.', '리프트 룿쉐아 쳼 례스뜨니쯰', '계단보다 엘리베이터가 더 좋아.', '리프트(엘리베이터는), 룿쉐아(더 좋다), 쳼(~보다), 례스뜨니쯰(계단보다)'),
    SpoonfedSentence(591, 'Где ты будешь завтра?', '그졔 띄 부지쉬 자프뜨라', '너는 내일 어디에 있을 거야?', '그졔(어디에), 띄(너는), 부지쉬(있을 거니), 자프뜨라(내일)'),
    SpoonfedSentence(592, 'В следующем месяце я буду в Москве.', '브 슬례두유쉼 몌씨쩨 야 부두 브 마스크볘', '나는 다음달에 모스크바에 있을 거야.', '브(~에), 슬례두유쉼(다음의), 몌씨쩨(달에), 야(나는), 부두(있을 것이다), 브(~에), 마스크볘(모스크바에)'),
    SpoonfedSentence(593, 'Где она была вчера?', '그졔 아나 브일라 프체라', '그녀는 어제 어디에 있었니?', '그졔(어디에), 아나(그녀는), 브일라(있었니), 프체라(어제)'),
    SpoonfedSentence(594, 'Я люблю водку больше, чем пиво.', '야 류블류 보드꾸 볼쉐, 쳼 삐바', '나는 맥주보다 보드카가 더 좋아.', '야(나는), 류블류(좋아한다), 보드꾸(보드카를), 볼쉐(더 크게, 많이), 쳼(~보다), 삐바(맥주보다)'),
    SpoonfedSentence(595, 'Что вы хотите спросить?', '시으또 븨 하찌쩨 스쁘라앁찌', '당신은 무엇을 물어보고 싶나요?', '시으또(무엇을), 븨(당신은), 하찌쩨(원하시나요), 스쁘라앁찌(물어보는 것을)'),
    SpoonfedSentence(596, 'Спроси ее.', '스쁘라씨 이요', '그녀에게 물어봐.', '스쁘라씨(물어봐라), 이요(그녀에게)'),
    SpoonfedSentence(597, 'Она спросила меня, где ты.', '아나 스쁘라씰라 미냐, 그졔 띄', '그녀는 나에게 너가 어디에 있는지 물었어.', '아나(그녀는), 스쁘라씰라(물었다), 미냐(나에게), 그졔(어디에), 띄(너가)'),
    SpoonfedSentence(598, 'Я ответил коротко.', '야 아뜨볘찔 꼬라뜨까', '저는 짧게 대답했어요.', '야(나는), 아뜨볘찔(대답했다), 꼬라뜨까(짧게)'),
    SpoonfedSentence(599, 'У нее короткие руки и длинные ноги.', '우 니요 까로뜨끼에 루끼 이 들린늬에 노기', '그녀는 팔은 짧고 다리는 길어.', '우(~에게는), 니요(그녀의), 까로뜨끼에(짧은), 루끼(팔들이), 이(그리고), 들린늬에(긴), 노기(다리들이)'),
    SpoonfedSentence(600, 'Мне нужен длинный инструмент.', '므녜 누즌 들린늬이 인스뜨루몐트', '나는 길다란 도구가 필요해.', '므녜(나에게는), 누즌(필요하다), 들린늬이(긴), 인스뜨루몐트(도구가)'),
